/** BITMAPINFOHEADER, uncompressed BGR, padded scanlines stored bottom first. */
public static void bmp(int width, int height, Rows rows, OutputStream out, long budget) throws IOException {
    bitmap(width, height, rows, out, budget, true);
}

/** Packed Windows DIB: BITMAPINFOHEADER and pixels, without the 14-byte BMP file header. */
public static void dib(int width, int height, Rows rows, OutputStream out, long budget) throws IOException {
    bitmap(width, height, rows, out, budget, false);
}

private static void bitmap(int width, int height, Rows rows, OutputStream out, long budget, boolean fileHeader) throws IOException {
    long stride = ((long) width * 3 + 3) & ~3L;
    long bytes = stride * height;
    check(width, height, budget, stride + (long) width * 4 + 65536);
    if (stride > Integer.MAX_VALUE - 8 || bytes > 0xffffffffL - 54)
        throw new Failure(1, "The image exceeds the BMP file-size limit.");
    if (fileHeader) {
        out.write('B'); out.write('M'); little(out, bytes + 54, 4);
        little(out, 0, 4); little(out, 54, 4);
    }
    little(out, 40, 4);
    little(out, width, 4); little(out, height, 4); little(out, 1, 2); little(out, 24, 2);
    little(out, 0, 4); little(out, bytes, 4);
    little(out, 0, 4); little(out, 0, 4); little(out, 0, 4); little(out, 0, 4);
    int[] pixels = new int[width]; byte[] row = new byte[(int) stride];
    for (int y = height - 1; y >= 0; y--) {
        rows.read(y, pixels);
        for (int x = 0, i = 0; x < width; x++) {
            int colour = pixels[x];
            row[i++] = (byte) colour; row[i++] = (byte) (colour >>> 8); row[i++] = (byte) (colour >>> 16);
        }
        out.write(row);
    }
}

@Test fun uncompressedAndDeflateExportsPreserveAllOpaquePixels() {
    val input = source()
    try {
        for (compressed in listOf(false, true)) {
            val file = File.createTempFile("tiff-roundtrip-", ".bin", context.cacheDir)
            try {
                TiffCodec.encode(input, file, compressed, budget)
                assertTrue(TiffCodec.isTiff(file))
                assertEquals(ImageDimensions(37, 29), TiffCodec.dimensions(file))
                // The encoded Compression tag must match the chosen Save as setting.
                assertEquals(if (compressed) 8 else 1, compressionTag(file))
                val output = TiffCodec.decode(file, ImageDimensions(37, 29), budget)
                try {
                    for (y in 0 until input.height) for (x in 0 until input.width)
                        assertEquals("compressed=$compressed $x,$y", input.getPixel(x,y), output.getPixel(x,y))
                } finally { output.recycle() }
            } finally { file.delete() }
        }
    } finally { input.recycle() }
}

static void colours(BufferedImage image,int... expected) {
    check(expected.length==image.getWidth()*image.getHeight(),"fixture dimensions");int i=0;
    for(int y=0;y<image.getHeight();y++)for(int x=0;x<image.getWidth();x++)
        check((image.getRGB(x,y)&0xffffff)==(expected[i++]&0xffffff),"pixel "+x+","+y+": "+Integer.toHexString(image.getRGB(x,y)));
}
static int colour(int x,int y) {return 0xff000000 | ((x*19+y*37)&255)<<16 | ((x*113+y*41)&255)<<8 | ((x*71+y*17)&255);}
static byte[] encode(int width,int height,boolean dib,long budget) throws Exception {
    ByteArrayOutputStream out=new ByteArrayOutputStream();LegacyImageEncoder.Rows rows=(y,row)->{for(int x=0;x<width;x++)row[x]=colour(x,y);};
    if(dib)LegacyImageEncoder.dib(width,height,rows,out,budget);else LegacyImageEncoder.bmp(width,height,rows,out,budget);return out.toByteArray();
}
static void output() throws Exception {
    for(int width:new int[]{1,2,3,4,19,2057})for(int height:new int[]{1,17}) {
        byte[] dib=encode(width,height,true,256L<<20),bmp=encode(width,height,false,256L<<20);
        check(dib[0]==40 && dib[1]==0 && dib.length==bmp.length-14,"true packed DIB header");
        check(Arrays.equals(dib,Arrays.copyOfRange(bmp,14,bmp.length)),"DIB payload same as BMP");
        BufferedImage image=decode(dib,width,height);
        for(int y=0;y<height;y++)for(int x=0;x<width;x++)check(image.getRGB(x,y)==colour(x,y),"exact round trip");
    }
